<?php
session_start(); require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_once __DIR__ . '/includes/audit.php';
$adminExists = (bool) $pdo->query("SELECT 1 FROM users u JOIN roles r ON r.id = u.role_id WHERE r.role_name = 'admin' LIMIT 1")->fetchColumn();
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !$adminExists) { $username = trim($_POST['username'] ?? ''); $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? ''; $roleId = $pdo->query("SELECT id FROM roles WHERE role_name = 'admin'")->fetchColumn();
    if (!verifyCsrfToken($_POST['csrf_token'] ?? null) || $username === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 8) { flash('danger', 'Use a username, valid email, and password of at least 8 characters.'); }
    else { try { $insert = $pdo->prepare('INSERT INTO users (role_id, username, email, password_hash, status) VALUES (:role_id, :username, :email, :password_hash, \'active\')'); $insert->execute([':role_id' => $roleId, ':username' => $username, ':email' => $email, ':password_hash' => password_hash($password, PASSWORD_DEFAULT)]); logAudit('ADMIN_CREATED', 'user', (int) $pdo->lastInsertId(), 'Initial demo administrator created.'); flash('success', 'Admin account created. You can now log in.'); redirect('login.php'); } catch (PDOException $exception) { flash('danger', 'Could not create the admin account. Username or email may already exist.'); } }
}
$pageTitle = 'Administrator Setup'; require __DIR__ . '/includes/header.php';
?><div class="setup-shell"><div class="setup-card"><p class="eyebrow">Initial configuration</p><h1 class="h3">Administrator Setup</h1><?php if ($adminExists): ?><div class="alert alert-info">An administrator account already exists. Use the sign-in page.</div><a class="btn btn-primary" href="login.php">Go to sign in</a><?php else: ?><p class="text-muted">Create the first administrator for this hospital portal.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label class="form-label">Username</label><input class="form-control mb-3" name="username" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><button class="btn btn-primary">Create administrator</button></form><?php endif; ?></div></div><?php require __DIR__ . '/includes/footer.php'; ?>